SELECT t_sprinkler.*, t_damaged_sprinkler.* FROM t_damaged_sprinkler LEFT JOIN t_sprinkler ON t_sprinkler.sprinkler_id = t_damaged_sprinkler.sprinkler_id
t_sprinkler.deleted_flag = #{queryForm.deletedFlag}
AND INSTR(t_sprinkler.sprinkler_serial,#{queryForm.sprinklerSerial})
AND INSTR(t_sprinkler.history,#{queryForm.history})
AND t_sprinkler.disabled_flag = #{queryForm.disabledFlag}
AND DATE_FORMAT(t_damaged_sprinkler.ret_warehouse_date, '%Y-%m-%d') >= #{joinForm.retWarehouseDateStartTime}
AND DATE_FORMAT(t_damaged_sprinkler.ret_warehouse_date, '%Y-%m-%d') <= #{joinForm.retWarehouseDateEndTime}
AND INSTR(t_damaged_sprinkler.note1,#{joinForm.note1})
AND INSTR(t_damaged_sprinkler.damaged_reason_type,#{joinForm.damagedReasonType})
AND INSTR(t_damaged_sprinkler.real_damaged_reason,#{joinForm.realDamagedReason})
ORDER BY t_sprinkler.create_time DESC

